// Данные пинов №1671–1720 и постов Facebook EN №225–274 (tools/pins/site5.js, tools/fb/fb_site5.js).
// Факты — только с сайта: content/wobbleland.json, docs/wobbleland.md, docs/postcards.md, docs/games.md, описания страниц (meta description).
// fb: [короткий заголовок, Тип, EN, RU для Threads ≤500, Праздник|null]. Картинка поста = сам пин.
const W = 'Зима', Y = 'Круглый год';
const TOP = {
  wl: 'Cozy games, Pixel art, Fantasy map, Worldbuilding, Indie art website',
  pc: 'Free ecards, Animated greeting cards, Send a card online, Thoughtful gift ideas',
  tools: 'Art resources, Tools for artists, Color palettes, Drawing practice, Free art lessons',
  games: 'Cozy games, Pixel art games, Browser games, Cute websites, Cozy aesthetic',
  themes: 'Drawing prompts, Sketchbook ideas, What to draw, Drawing challenge, Art inspiration',
};
const crest = k => `wobbleland/crest-${k}.png`;
const walk = k => `s5/walk-${k}.png`;
const WC = [180, 0, 1250, 758];
const WB = [330, 0, 1000, 758]; // крупнее, для одиночного кадра // кадр улицы без станции по краю

// ——— 1671–1680: Воббленд ———
const wl = [
  { type: 'shot', th: 'night', kick: 'wobbleland · an island drawn in pixels', h: 'What is <em>Wobbleland</em>?', src: 'shots/wobble.png', crop: [60, 40, 1860, 1340],
    cap: 'eleven towns, one wobble', chips: ['🗺 zoom the map', '🏘 11 towns', '🎉 holidays', '🍲 recipes'], cta: 'Open the map', tpl: 'Арт',
    title: 'What Is Wobbleland? A Cozy Pixel Island of 11 Towns You Can Explore Online',
    desc: 'Wobbleland is the little fairy-tale island on pigeonpolly.com: a pixel map of eleven towns with their own crests, holidays, recipes and residents. Zoom in, tap a town, take a walk down its street — Polly the pigeon is your guide. Free to explore.',
    alt: 'Pixel art map of the island Wobbleland with eleven towns, roads and a railway, from the website Pigeon Polly Art Lab.',
    fb: ['What is Wobbleland', 'Про сайт',
      `People ask me what Wobbleland is, so here is the short version: it is an island that lives on my site.\n\nEleven towns, each with its own crest, motto, holidays and food. A snail town where nothing is rushed, a lemon valley, a noodle town, a cheese river valley — and one grey building where wrongdoers write confessions until one finally rings true. You can zoom into the pixel map and walk down every street. Which town would you visit first?`,
      `Меня спрашивают, что такое Воббленд, так что коротко: это остров, который живёт на моём сайте.\n\nОдиннадцать городов, у каждого свой герб, девиз, праздники и еда. Улиточный город, где никто не спешит, лимонная долина, город лапши, сырная долина — и одно серое здание, где провинившиеся пишут признания, пока одно не окажется правдой. Пиксельную карту можно приблизить и пройти по каждой улице. В какой город вы бы пошли первым?`] },
  { type: 'rows', th: 'paper', kick: 'wobbleland · 11 towns, 11 mottos', h: 'Every town has a <em>motto</em>', ic: 74, top: 250, cta: 'Meet the towns', tpl: 'Серия',
    items: ['newwobbleton', 'snailhollow', 'lemonvale', 'noodleford', 'kettleford', 'buttonspire', 'jamshire', 'cheddarford', 'pinecrust', 'maplewink', 'department'].map(k => ({ ic: crest(k), a: k === 'department' ? 'The Department' : (k === 'lemonvale' ? 'LemonVale' : require('../../content/wobbleland.json').cities.find(c => c.key === k).name), b: '“' + require('../../content/wobbleland.json').cities.find(c => c.key === k).motto + '”' })),
    title: '11 Town Mottos From a Fairy-Tale Island — “Better Late than Faster” and More',
    desc: 'Snailhollow says “Better Late than Faster”, LemonVale shouts “Squeeze the Day!”, Noodleford whispers “Slurp Loud, Live Long”. These are the eleven towns of Wobbleland, my pixel island on pigeonpolly.com — each with a crest, a motto and its own little life.',
    alt: 'List of eleven pixel crests of the towns of Wobbleland with their mottos, such as “Better Late than Faster” and “Squeeze the Day!”.',
    fb: ['Eleven mottos', 'Про сайт',
      `If your town had a motto, what would it be?\n\nIn Wobbleland every town has one. Snailhollow: “Better Late than Faster.” LemonVale: “Squeeze the Day!” Noodleford: “Slurp Loud, Live Long.” Cheddarford: “Sharp Minds, Sharper Cheddar.” And the Department of Reflection on the Deed, which is half prison, half filing office: “No Truth, No Exit.” I think about Snailhollow’s motto every Monday morning. Which one is yours?`,
      `Если бы у вашего города был девиз, какой?\n\nВ Воббленде он есть у каждого. Snailhollow: «Лучше поздно, чем быстрее». LemonVale: «Выжми этот день!» Noodleford: «Хлюпай громко, живи долго». Cheddarford: «Острый ум, ещё острее чеддер». А у Департамента, который наполовину тюрьма, наполовину канцелярия: «Без правды нет выхода». Я вспоминаю девиз Snailhollow каждый понедельник утром. А какой ваш?`] },
  { type: 'shot', th: 'sage', kick: 'wobbleland · take a walk', h: 'A slow walk through <em>Snailhollow</em>', src: walk('snailhollow'), crop: WB, px: 1,
    cap: 'better late than faster', chips: ['🐌 5 tiny shells are hidden', '🚶 tap to walk', '💬 talk to residents'], cta: 'Take a walk', tpl: 'Арт', link: '/wobbleland/#walk-snailhollow',
    title: 'Take a Slow Pixel Walk Through Snailhollow, a Moss-Covered Town Where No One Hurries',
    desc: 'Snailhollow is the slowest town in Wobbleland: moss on the roofs, snails of every size on the streets, home of Mr. Chew and Detective Titos. On pigeonpolly.com you can walk down its pixel street, talk to residents and look for five tiny snail shells hidden somewhere in town.',
    alt: 'Pixel art street of Snailhollow: green moss-covered houses, a notice board, a giant snail shell and a small purple pigeon walking.',
    fb: ['A walk through Snailhollow', 'Про сайт',
      `Snailhollow is the town where I would go on a bad week.\n\nThe roofs are covered in moss, snails of every size live on the streets, and the motto is “Better Late than Faster”. Mr. Chew and Detective Titos live here too. On my site you can walk down its little pixel street, talk to the residents at their doors and look for five tiny snail shells hidden somewhere in town. Have you ever found all five?`,
      `Snailhollow — город, куда я бы поехала в тяжёлую неделю.\n\nКрыши во мху, на улицах улитки всех размеров, а девиз — «Лучше поздно, чем быстрее». Здесь живут Мистер Чу и детектив Титос. На сайте можно пройтись по его маленькой пиксельной улице, поговорить с жителями у дверей и поискать пять крошечных раковин, спрятанных где-то в городе. Вы находили все пять?`] },
  { type: 'tiles', th: 'cream', kick: 'wobbleland · eleven little streets', h: 'Every town has <em>its own street</em>', cols: 2, tileH: 250, top: 290,
    items: [['lemonvale', 'LemonVale', 'lemons, sea and sand'], ['noodleford', 'Noodleford', 'lanterns and steaming windows'], ['kettleford', 'Kettleford', 'a giant copper samovar'], ['buttonspire', 'Buttonspire', 'a tower of buttons'], ['maplewink', 'Maplewink', 'maple syrup and golden leaves'], ['department', 'The Department', 'no truth, no exit']].map(([k, a, b]) => ({ src: walk(k), crop: WC, px: 1, label: a, sub: b })),
    cta: 'Walk the towns', tpl: 'Серия',
    title: 'Six Pixel Art Towns From One Cozy Island — Lemons, Noodles, Buttons and Tea',
    desc: 'LemonVale with its sea and sand, Noodleford with lanterns, Kettleford with a giant copper samovar, Buttonspire with its tower of buttons. Every town of Wobbleland on pigeonpolly.com has its own pixel street you can walk, with residents, a food stall and a holiday board.',
    alt: 'Six pixel art street scenes of towns from Wobbleland: lemon town by the sea, noodle town, tea town with a samovar, purple button town, autumn maple town and a grey stone town.',
    fb: ['Six little streets', 'Про сайт',
      `Six towns, six streets, six very different moods.\n\nLemonVale by the sea, where the old money was called “wedges”. Noodleford with lanterns of dried noodles. Kettleford, where every household keeps at least three kettles. Buttonspire with its tower studded with buttons. Maplewink in golden leaves. And the grey Department, where nobody is in a hurry to leave. Each one is a little pixel street on my site that you can walk. Which mood is yours today?`,
      `Шесть городов, шесть улиц, шесть очень разных настроений.\n\nLemonVale у моря, где старые деньги назывались «дольками». Noodleford с фонарями из сушёной лапши. Kettleford, где в каждом доме минимум три чайника. Buttonspire с башней в пуговицах. Maplewink в золотых листьях. И серый Департамент, откуда никто не спешит уйти. Каждый — маленькая пиксельная улица на сайте, по которой можно пройтись. Какое настроение ваше сегодня?`] },
  { type: 'rows', th: 'night', kick: 'wobbleland · holidays to steal', h: 'Holidays I wish <em>were real</em>', ic: 80, cta: 'See the calendar', tpl: 'Темы', season: W,
    items: [['kettleford', 'Great Whistle Day', 'the whole town boils its kettles at once — the louder, the luckier'], ['noodleford', 'Long Noodle Eve', 'one noodle is stretched through every street as a wish for a long life'], ['buttonspire', 'Button Tree Night', 'a fir tree decorated only with buttons found this year'], ['kettleford', 'Frosted Spout Day', 'kettles on every windowsill steam the glass for frost patterns'], ['snailhollow', 'Slowstep Festival', 'who can walk a street the slowest without stopping'], ['jamshire', 'Jar Lantern Night', 'empty jam jars become lanterns on every cellar stair'], ['cheddarford', 'Golden Grid Night', 'count the squares of a cheese waffle instead of stars'], ['buttonspire', 'Festival of the Lost Button', 'losing a button means luck, finding one means a new friend']].map(([k, a, b]) => ({ ic: crest(k), a, b })),
    title: '8 Cozy Fantasy Holidays to Steal for Your Own Winter — From a Fairy-Tale Island',
    desc: 'Boil every kettle in town at once, stretch one noodle through all the streets, decorate a tree with nothing but buttons. These are holidays of Wobbleland, the pixel island on pigeonpolly.com — with a tear-off calendar and a little gift for your bird on each holiday.',
    alt: 'List of eight cozy holidays of the fantasy island Wobbleland with pixel town crests: Great Whistle Day, Long Noodle Eve, Button Tree Night and more.',
    fb: ['Holidays to steal', 'Про сайт',
      `Some holidays from Wobbleland that I would happily steal for real life.\n\nGreat Whistle Day: the whole town boils its kettles at once, and the louder the whistle, the luckier the year. Long Noodle Eve: one single noodle is stretched through every street, and whoever lets it break washes everyone’s dishes. Button Tree Night: a fir tree decorated only with buttons found this year. On the site each holiday has a tear-off calendar page. Which one would you celebrate?`,
      `Несколько праздников Воббленда, которые я бы с радостью украла в настоящую жизнь.\n\nДень Большого Свиста: весь город одновременно кипятит чайники, и чем громче свист, тем удачнее год. Канун Длинной Лапши: одну лапшу протягивают через все улицы, а у кого порвётся — тот моет всем посуду. Ночь Пуговичной Ёлки: ёлка только из пуговиц, найденных за год. На сайте у каждого праздника есть листок отрывного календаря. Какой бы вы отпраздновали?`] },
  { type: 'rows', th: 'kraft', kick: 'wobbleland · polly’s recipe book', h: 'What they eat <em>in Wobbleland</em>', ic: 84, cta: 'Open the recipe book', tpl: 'Темы',
    items: [['noodleford', 0, 'clear night broth with onion and egg'], ['maplewink', 0, 'fluffy pancakes swimming in maple syrup'], ['snailhollow', 0, 'herbal tea with mint and forest moss'], ['pinecrust', 0, 'nut pie with an extra-crisp crust'], ['buttonspire', 0, 'stew with button-shaped bread dumplings'], ['jamshire', 0, 'a different jam in every layer'], ['cheddarford', 0, 'thick soup in a bread bowl with melted cheese'], ['kettleford', 0, 'black coffee brewed only in copper cezves'], ['department', 0, 'tastes better the more honest you’ve been today']].map(([k, i, b]) => ({ ic: `wobbleland/dish-${k}-${i}.png`, a: WLd(k, i), b })),
    title: '9 Cozy Fantasy Foods From a Pixel Island — Brothmoon Soup, Regret Stew and More',
    desc: 'Brothmoon Soup from Noodleford, Mossy Tea from Snailhollow, Jamshire Layer Cake with a different jam in every layer — and Regret Stew, which tastes better the more honest you have been that day. Polly’s recipe book of Wobbleland lives on pigeonpolly.com.',
    alt: 'Pixel art dishes from Wobbleland with names: Brothmoon Soup, Maple-Soaked Pancakes, Mossy Tea, Pine Nut Pie, Button Stew and others.',
    fb: ['Regret Stew', 'Про сайт',
      `Polly keeps a recipe book of Wobbleland, and my favourite page is Regret Stew.\n\nIt is a plain grey stew served at the Department, and locals swear it tastes better the more honest you’ve been that day. Next to it: Brothmoon Soup from Noodleford, Mossy Tea from Snailhollow, a Jamshire cake with a different jam in every layer. Every dish is drawn in pixels. Which one would you order?`,
      `Полли ведёт книгу рецептов Воббленда, и моя любимая страница — Рагу сожаления.\n\nЭто простое серое рагу из Департамента, и местные клянутся, что оно тем вкуснее, чем честнее ты был сегодня. Рядом — лунный бульон из Noodleford, моховой чай из Snailhollow, торт из Jamshire, где в каждом слое своё варенье. Каждое блюдо нарисовано в пикселях. Что бы вы заказали?`] },
  { type: 'tiles', th: 'rose', kick: 'wobbleland · neighbours', h: 'Meet the <em>neighbours</em>', cols: 3, top: 290, tileH: 250,
    items: [['toad-mortimer', 'Toad Mortimer', 'retired grim reaper'], ['dr-dripsson', 'Dr. Dripsson', 'spider barista'], ['sir-puddlesworth', 'Sir Puddlesworth', 'puddle inspector'], ['bramwell-bear', 'Bramwell Bear', 'professional winter sleeper'], ['wren-windlow', 'Wren Windlow', 'counts raindrops'], ['sew-sew-patty', 'Sew-Sew Patty', 'mends broken hearts'], ['ghostina-gravy', 'Ghostina Gravy', 'ghost chef'], ['count-hopula', 'Count Hopula', 'night carrot-juice bar'], ['rowena-ghostclaw', 'Rowena Ghostclaw', 'ghost food critic']].map(([k, a, b]) => ({ src: `wobbleland/pt-${k}.png`, px: 1, label: a, sub: b })),
    cta: 'Meet everyone', tpl: 'Серия',
    title: 'Cozy Fantasy Character Ideas: a Retired Grim Reaper, a Spider Barista, a Puddle Inspector',
    desc: 'A toad who retired from being a grim reaper, a spider who runs a coffee shop, a knight whose job is inspecting puddles. These are residents of Wobbleland on pigeonpolly.com — you meet them at their doors when you walk through their towns.',
    alt: 'Grid of nine pixel art character portraits from Wobbleland with their jobs: retired grim reaper toad, spider barista, puddle inspector, winter-sleeping bear and others.',
    fb: ['Neighbours', 'Про сайт',
      `Some of my favourite neighbours in Wobbleland.\n\nToad Mortimer, a retired grim reaper. Dr. Dripsson, a spider barista. Sir Puddlesworth, whose job is inspecting puddles. Bramwell Bear, a professional winter sleeper. Wren Windlow, who counts raindrops on the windowsill. Sew-Sew Patty, a pincushion who mends broken hearts. You meet them at their doors when you walk through their towns. Whose job would you take?`,
      `Несколько любимых соседей из Воббленда.\n\nЖаба Мортимер — смерть на пенсии. Доктор Дрипсон — паук-бариста. Сэр Лужворт — инспектор луж. Медведь Брамвелл — профессиональный зимний соня. Рен Виндлоу считает капли дождя на подоконнике. Шью-Шью Пэтти — подушечка для иголок, которая чинит разбитые сердца. Их встречаешь у дверей, когда гуляешь по их городам. Чью работу вы бы взяли?`] },
  { type: 'shot', th: 'studio', kick: 'wobbleland · the strangest building', h: 'Half prison, half <em>filing office</em>', src: walk('department'), crop: WB, px: 1,
    cap: 'no truth, no exit', chips: ['📝 write until it rings true', '📅 Confession Day, April 1'], cta: 'Visit (if you dare)', tpl: 'Мем', link: '/wobbleland/#walk-department',
    title: 'A Fantasy Prison Where You Write Confessions Until One Rings True — Wobbleland',
    desc: 'The Department of Reflection on the Deed stands alone on the road between Buttonspire and Noodleford. Wrongdoers serve their sentence writing endless reflections until a confession finally rings true. On April 1 an honest — or honestly funny — confession can get you out early. A corner of Wobbleland on pigeonpolly.com.',
    alt: 'Pixel art of a grey rainy street with a tall stone building, the Department of Reflection on the Deed from the island Wobbleland.',
    fb: ['No truth, no exit', 'Про сайт',
      `Every fairy-tale island needs one grey building.\n\nIn Wobbleland it is the Department of Reflection on the Deed: half prison, half filing office. Wrongdoers sit there writing reflections until a confession finally rings true. On April 1 anyone who writes a genuinely honest, or genuinely funny, confession gets a shot at early release, and islanders mail in fake confessions just for fun. What would your confession be?`,
      `На каждом сказочном острове нужно одно серое здание.\n\nВ Воббленде это Департамент размышлений о содеянном: наполовину тюрьма, наполовину канцелярия. Провинившиеся пишут там размышления, пока признание не прозвучит правдиво. 1 апреля тот, кто напишет по-настоящему честное или по-настоящему смешное признание, может выйти раньше, а жители присылают шуточные признания просто так. Каким было бы ваше?`] },
  { type: 'quote', th: 'sky', kick: 'wobbleland · your guide', q: 'Greetings, dear reader. My name is Polly, and I am a pigeon. Though, to be entirely precise, I am not quite an ordinary representative of my species.', who: 'Polly, your feathered guide', src: 'shots/wobble.png', crop: [300, 200, 1300, 900], top: 560, ih: 700, cta: 'Read the story', tpl: 'Арт',
    title: 'A Pigeon Will Be Your Guide: Read the Story of a Cozy Pixel Island',
    desc: 'Wobbleland opens with a letter from Polly, a pigeon who is not quite an ordinary representative of her species. Read the story of the island on pigeonpolly.com, then explore the map of eleven towns with her as your guide.',
    alt: 'Quote from Polly the pigeon introducing the island Wobbleland, above a detail of the colourful pixel map of the island.',
    fb: ['Your feathered guide', 'Полли',
      `“Greetings, dear reader. My name is Polly, and I am a pigeon.”\n\nThat is how Wobbleland begins on my site: with a long, slightly pompous letter from Polly, who insists she is not quite an ordinary representative of her species. She tells you about the island, its towns and its small secrets, and then she shows you the map. Do you like stories that start with a letter?`,
      `«Приветствую, дорогой читатель. Меня зовут Полли, и я голубь».\n\nТак на сайте начинается Воббленд: с длинного, немного важного письма Полли, которая настаивает, что она не совсем обычный представитель своего вида. Она рассказывает об острове, городах и маленьких тайнах, а потом показывает карту. Вы любите истории, которые начинаются с письма?`] },
  { type: 'tiles', th: 'sun', kick: 'wobbleland · pick your town', h: 'Which town would <em>you</em> live in?', cols: 2, tileH: 250, top: 290,
    items: [['snailhollow', 'Snailhollow', '“Better Late than Faster”'], ['lemonvale', 'LemonVale', '“Squeeze the Day!”'], ['kettleford', 'Kettleford', '“Brewing Joy, Hour by Hour”'], ['jamshire', 'Jamshire', '“Spread the Sweetness”'], ['pinecrust', 'Pinecrust', '“Crisp Outside, Warm Inside”'], ['cheddarford', 'Cheddarford', '“Sharp Minds, Sharper Cheddar”']].map(([k, a, b]) => ({ src: walk(k), crop: WC, px: 1, label: a, sub: b })),
    cta: 'Choose your town', tpl: 'Мем',
    title: 'Which Cozy Fantasy Town Would You Live In? Snails, Lemons, Tea, Jam, Pies or Cheese',
    desc: 'A slow snail town, a sunny lemon valley, a tea-and-coffee town, a jam town, a forest bakery town or a cheese valley. Pick yours — then go for a walk down its pixel street on pigeonpolly.com.',
    alt: 'Six pixel art town streets from Wobbleland with their mottos, asking which cozy town you would live in.',
    fb: ['Pick your town', 'Про сайт',
      `Quick question: which town would you live in?\n\nSnailhollow, where nothing is ever rushed. LemonVale, where no traveller leaves hungry. Kettleford, where every house keeps at least three kettles “just in case”. Jamshire, where “having tea” means “gathering for a jar”. Pinecrust, smelling of pine and pastry. Or Cheddarford, with caves full of cheese. I keep changing my answer. What is yours?`,
      `Быстрый вопрос: в каком городе вы бы жили?\n\nSnailhollow, где никто никогда не спешит. LemonVale, откуда ни один путник не уходит голодным. Kettleford, где в каждом доме минимум три чайника «на всякий случай». Jamshire, где «попить чаю» значит «собраться у банки». Pinecrust, где пахнет хвоей и выпечкой. Или Cheddarford с пещерами, полными сыра. Я всё время меняю ответ. А ваш?`] },
];
function WLd(k, i) { return require('../../content/wobbleland.json').cities.find(c => c.key === k).dishes[i].name; }

// ——— 1681–1690: открытки ———
const PCH = ['✦ it moves', '✉ by email', '♥ free'];
const pc = [
  { type: 'steps', th: 'cream', kick: 'no stamps · no post office', h: 'Send a postcard in <em>one minute</em>', cta: 'Send one now', tpl: 'Процесс', season: Y,
    steps: [{ id: 'sunshine', h: 'Pick a card', p: 'twenty animated postcards with my art' }, { id: 'thanks', h: 'Write a few words', p: 'your message, their name and email' }, { h: 'It flies by email', p: 'they open the envelope and the card moves' }],
    title: 'How to Send a Postcard Online in One Minute — No Stamps, Free Animated Ecards',
    desc: 'No stamps, no post office, no queue. On pigeonpolly.com you pick one of twenty animated postcards with my paintings, write a few words, add their email — and it arrives in a minute. Free, you just sign in.',
    alt: 'Three steps to send an animated postcard from pigeonpolly.com: pick a card, write a message, it arrives by email in an envelope.',
    fb: ['No stamps needed', 'Про сайт',
      `I love paper postcards, but I never have stamps at home. So I made the next best thing.\n\nOn my site there are twenty animated postcards with my paintings. You pick one, write a few words and their email, and in a minute it lands in their inbox: an envelope, and inside a little card where snow falls or bubbles rise. No queue at the post office. Who was the last person you sent a postcard to?`,
      `Я люблю бумажные открытки, но дома никогда нет марок. Поэтому сделала почти то же самое.\n\nНа сайте двадцать живых открыток с моими картинами. Выбираешь, пишешь пару слов и почту — и через минуту она у адресата: конверт, а внутри открытка, где идёт снег или поднимаются пузырьки. Без очереди на почте. Кому вы последний раз отправляли открытку?`] },
  { type: 'tiles', th: 'pink', kick: 'one for every occasion', h: 'Birthday, love, thanks or <em>just because</em>', cols: 3,
    items: [['bday-cake', 'Birthday'], ['love-polly', 'Love'], ['thanks', 'Thank you'], ['easter', 'Easter'], ['march8', 'Women’s Day'], ['ligo', 'Midsummer'], ['halloween', 'Halloween'], ['coffee', 'Cozy autumn'], ['busy', 'Just because']].map(([id, a]) => ({ pc: id, label: a })),
    cta: 'Pick a postcard', tpl: 'Серия', season: Y,
    title: 'Animated Ecards for Every Occasion — Birthday, Love, Thank You or Just Because',
    desc: 'Birthday, love, thank you, Easter, Women’s Day, Midsummer, Halloween, a cozy autumn hello or no reason at all. Twenty animated postcards with my art on pigeonpolly.com, free to send by email with your own words.',
    alt: 'Grid of nine animated postcards by Pigeon Polly for birthday, love, thank you, Easter, Women’s Day, Midsummer, Halloween, autumn and just because.',
    fb: ['A card for every occasion', 'Про сайт',
      `Not every postcard needs a holiday.\n\nOn my site there are cards for birthdays and Valentine’s Day, for Easter, Midsummer and Halloween — and a whole group for friends: a thank-you, “sending you sunshine”, a cozy coffee one, a bubble bath one for someone who is tired. Twenty in total, all moving, all free to send by email with your own words. What occasion do you send cards for most?`,
      `Не каждой открытке нужен праздник.\n\nНа сайте есть открытки ко дню рождения и Дню святого Валентина, к Пасхе, Лиго и Хэллоуину — и целая группа для друзей: «спасибо», «посылаю немного солнца», уютная с кофе, с ванной с пузырьками для уставшего человека. Всего двадцать, все живые, отправить по почте со своими словами — бесплатно. По какому поводу вы чаще отправляете открытки?`] },
  { type: 'pc', th: 'night', id: 'fireworks', kick: 'new year postcard · free', h: 'Send <em>fireworks</em> by email', cap: 'the sky really lights up', chips: PCH, cta: 'Send it free', tpl: 'Арт', season: W,
    title: 'Send Fireworks by Email — Animated New Year Ecard With Pixel Art, Free',
    desc: 'A pixel New Year night where the fireworks really go off. One of the animated postcards on pigeonpolly.com: write your wishes, add their email and it arrives in a minute. Free, you just sign in.',
    alt: 'Animated New Year postcard by Pigeon Polly: pixel art night sky with colourful fireworks over a little town.',
    fb: ['Fireworks by email', 'Про сайт', `Fireworks are loud, expensive and scare the dogs. So here are quiet ones.\n\nThis New Year postcard is a little pixel night where the sky lights up again and again, every few seconds, for as long as they look at it. You write your wishes, add their email, and it arrives in a minute. Free on my site. Who would you send the first fireworks of the year to?`,
      `Фейерверки громкие, дорогие и пугают собак. Поэтому вот тихие.\n\nЭта новогодняя открытка — маленькая пиксельная ночь, где небо вспыхивает снова и снова, каждые несколько секунд, пока на неё смотрят. Пишешь пожелания, указываешь почту — и она приходит через минуту. Бесплатно на сайте. Кому вы отправили бы первый фейерверк года?`, 'Новый год'] },
  { type: 'pc', th: 'sage', id: 'ligo', kick: 'midsummer postcard', h: 'A <em>Midsummer</em> card from Riga', cap: 'flower wreaths and the shortest night', chips: PCH, cta: 'Send a postcard', tpl: 'Арт', season: 'Лето',
    title: 'Midsummer Postcard From Latvia: Pixel Art Līgo Night Ecard With a Flower Wreath',
    desc: 'In Latvia we celebrate Līgo — Midsummer — with flower wreaths, songs and the shortest night of the year. This animated pixel postcard on pigeonpolly.com carries a bit of that night: free to send by email with your own words.',
    alt: 'Animated Midsummer postcard by Pigeon Polly: pixel art pigeon in a flower wreath on a summer night, Latvian Līgo celebration.',
    fb: ['Līgo in a postcard', 'Про сайт', `I live in Riga, and in Latvia Midsummer is a big deal. We call it Līgo.\n\nFlower and oak-leaf wreaths, songs, cheese with caraway, and the shortest night of the year when nobody really sleeps. I drew a little pixel postcard for it with Polly in a wreath. It moves, it goes by email, and it is free to send from my site. How do you celebrate the longest day where you live?`,
      `Я живу в Риге, а в Латвии середина лета — большой праздник. Мы называем его Лиго.\n\nВенки из цветов и дубовых листьев, песни, сыр с тмином и самая короткая ночь в году, когда почти никто не спит. Я нарисовала для него маленькую пиксельную открытку с Полли в венке. Она живая, уходит по почте и отправляется с сайта бесплатно. Как празднуют самый длинный день там, где вы живёте?`] },
  { type: 'envelope', th: 'kraft', id: 'love-polly', kick: 'it arrives like this', h: 'An envelope in their inbox. <em>Open me.</em>', cap: 'and inside, the card moves', cta: 'Send one', tpl: 'Арт', season: Y,
    title: 'What Your Friend Sees: an Envelope in Their Inbox and an Animated Card Inside',
    desc: 'The postcard arrives as an email with a moving picture and a button “Open the postcard”. Inside — your words and my painting, alive. Send one free from pigeonpolly.com; you just sign in.',
    alt: 'A kraft envelope with a red wax seal and an animated love postcard by Pigeon Polly coming out of it.',
    fb: ['Open me', 'Про сайт', `What the person on the other side sees: a letter in their inbox, a moving picture and a button that says “Open the postcard”.\n\nInside are your words, written in a handwritten font, and my painting, alive: hearts float, snow falls, bubbles rise. I wanted it to feel a bit like opening a real envelope. Do you still have a box of old postcards somewhere?`,
      `Что видит человек на той стороне: письмо во входящих, живую картинку и кнопку «Открыть открытку».\n\nВнутри — твои слова рукописным шрифтом и моя картина, живая: летят сердечки, падает снег, поднимаются пузырьки. Хотелось, чтобы это немного напоминало настоящий конверт. У вас где-нибудь ещё хранится коробка со старыми открытками?`, 'Valentine’s Day'] },
  { type: 'pc', th: 'studio', id: 'love-chew', kick: 'from a secret friend', h: 'Send it <em>anonymously</em>', cap: '— from a secret friend', chips: ['🕵 no name needed', '✉ by email', '♥ free'], cta: 'Be a secret friend', tpl: 'Арт', season: Y,
    title: 'Send an Anonymous Postcard to Someone — Be Their Secret Friend, Free Animated Ecard',
    desc: 'Want to cheer someone up without making it about you? On pigeonpolly.com you can send an animated postcard anonymously — it arrives signed “from a secret friend”. Free, you just sign in.',
    alt: 'Animated love postcard by Pigeon Polly with two snails and hearts, signed “from a secret friend”.',
    fb: ['A secret friend', 'Про сайт', `Sometimes you want to make someone’s day and stay completely invisible.\n\nWhen you send a postcard from my site, you can tick “anonymous”, and it arrives signed “from a secret friend”. A colleague who had a rough week, a neighbour who always says hello, someone you admire from a distance. They will never know it was you. Who would you send a secret postcard to?`,
      `Иногда хочется кого-то порадовать и остаться совсем невидимым.\n\nКогда отправляешь открытку с моего сайта, можно отметить «анонимно» — и она придёт с подписью «от тайного друга». Коллеге с тяжёлой неделей, соседу, который всегда здоровается, человеку, которым тихо восхищаешься. Он никогда не узнает, что это вы. Кому бы вы отправили тайную открытку?`] },
  { type: 'list', th: 'sun', art: '2023-mr-chew-australian-postal-snail-introduction', pos: '50% 40%', kick: 'no occasion needed', h: '12 tiny reasons to send a <em>postcard today</em>', cta: 'Send a postcard', tpl: 'Темы', season: Y,
    items: ['they passed a driving test', 'first day at a new job', 'it’s been a grey week', 'they finished a big project', 'you saw something that reminded you of them', 'their cat had a birthday', 'they made you laugh yesterday', 'it’s the first snow', 'they moved to a new city', 'you miss them', 'they helped and didn’t make a fuss', 'it’s Tuesday'],
    title: '12 Tiny Reasons to Send Someone a Postcard Today (No Holiday Needed)',
    desc: 'A driving test, a first day at work, the first snow, a grey week, a cat’s birthday — or just Tuesday. Twelve small reasons to send a postcard, and twenty animated ones with my art on pigeonpolly.com, free to send by email.',
    alt: 'List of twelve small reasons to send a postcard, with a painting of Mr. Chew the postal snail by Pigeon Polly.',
    fb: ['Twelve tiny reasons', 'Про сайт', `Most postcards are sent for big days. I think the small ones need them more.\n\nThey passed a driving test. First day at a new job. It has been a grey week. Their cat had a birthday. It is the first snow. They helped you and didn’t make a fuss. Or simply: it’s Tuesday and you miss them. That is why I made the animated postcards on my site free to send. What is your tiny reason this week?`,
      `Большинство открыток отправляют к большим дням. А мне кажется, маленьким они нужнее.\n\nСдал на права. Первый день на новой работе. Неделя была серой. У кота день рождения. Выпал первый снег. Помог и не сделал из этого события. Или просто вторник, и ты скучаешь. Поэтому живые открытки на сайте отправляются бесплатно. Какой у вас маленький повод на этой неделе?`] },
  { type: 'pair', th: 'sky', a: 'bath', b: 'sunshine', kick: 'postcard ping-pong', h: 'They can <em>answer</em> with a postcard', capA: 'you: “time to rest”', capB: 'them: “sending sunshine back”', cta: 'Start a ping-pong', tpl: 'Мем', season: Y,
    title: 'Postcard Ping-Pong: Send a Friend an Animated Card and Get One Back',
    desc: 'You send “time to rest and bubble”, they answer with “sending you sunshine”. Whoever gets a postcard from pigeonpolly.com can reply with one of their own. Twenty animated cards with my art, free to send.',
    alt: 'Two animated postcards by Pigeon Polly, a pigeon in a bubble bath and a pigeon on the beach, sent back and forth between friends.',
    fb: ['Postcard ping-pong', 'Про сайт', `My favourite thing that happens with the postcards: ping-pong.\n\nSomeone sends a friend the bubble bath card, “time to rest”. The friend opens it and answers with the beach one, “sending you sunshine”. And then it goes back again. It reminds me of passing notes in school, only with moving paintings. Who would you play postcard ping-pong with?`,
      `Моё любимое, что случается с открытками, — пинг-понг.\n\nКто-то отправляет подруге открытку с ванной: «пора отдохнуть». Подруга открывает и отвечает пляжной: «посылаю немного солнца». А потом обратно. Похоже на записки на уроках, только с живыми картинами. С кем бы вы сыграли в открыточный пинг-понг?`] },
  { type: 'pc', th: 'pink', id: 'bday-cake', kick: 'pov', h: 'POV: you remembered their birthday at <em>11:58 pm</em>', cap: 'it arrives in a minute. you’re safe.', chips: PCH, cta: 'Save the day', tpl: 'Мем', season: Y,
    title: 'POV: You Remembered Their Birthday at 11:58 pm — Send an Animated Card in a Minute',
    desc: 'Two minutes to midnight and you just remembered. Pick a birthday postcard on pigeonpolly.com, write a few words, add their email — it arrives in about a minute, with confetti falling over the cake. Free, you just sign in.',
    alt: 'Animated birthday postcard by Pigeon Polly with a cake and candles, meme caption about remembering a birthday at 11:58 pm.',
    fb: ['11:58 pm', 'Про сайт', `11:58 pm. You suddenly remember whose birthday it is today.\n\nThis is exactly the situation the birthday postcards on my site were made for. Pick the cake one, write two honest sentences, add the email — it arrives in about a minute, with confetti. Nobody needs to know about the 11:58 part. Has this ever happened to you, or are you the person who remembers everything?`,
      `23:58. Вы вдруг вспоминаете, чей сегодня день рождения.\n\nИменно для такой ситуации на сайте есть открытки ко дню рождения. Выбираешь с тортом, пишешь два честных предложения, указываешь почту — и примерно через минуту она на месте, с конфетти. Про 23:58 никому знать не обязательно. С вами такое бывало, или вы тот человек, который помнит всё?`] },
  { type: 'shot', th: 'cream', kick: 'a corner of my site', h: 'Where my art <em>travels by email</em>', src: 's5/postcards.png', crop: [180, 200, 1820, 1300], browser: 1, url: '/postcards/',
    cap: 'twenty cards · write your own words', chips: ['🎄 winter', '🎂 birthday', '♥ love', '🌷 seasons', '☕ friends'], cta: 'Send a gift', tpl: 'Арт', season: Y,
    title: 'A Free Website Where You Can Send Animated Art Postcards by Email',
    desc: 'The postcards page of pigeonpolly.com: twenty animated cards with my paintings and pixel scenes — winter, birthday, love, seasons and friends. Change the greeting, write your message, send it by email, even anonymously. Free, you just sign in.',
    alt: 'Screenshot of the postcards page on pigeonpolly.com with a pixel pigeon carrying a sack of gifts and a grid of animated postcards.',
    fb: ['Where art travels', 'Про сайт', `This is the corner of my site where paintings leave home.\n\nPixel Polly sits at the top with a sack of gifts, and below are twenty postcards: winter, birthday, love, seasons and friends. You can change the greeting on the card, write your own message and send it by email, even as a secret friend. It makes me happy every time I see a counter of sent cards go up. Which card would you send first?`,
      `Это уголок сайта, где картины уходят из дома.\n\nНаверху пиксельная Полли с мешком подарков, ниже двадцать открыток: зима, день рождения, любовь, времена года и друзья. Можно поменять надпись на открытке, написать своё послание и отправить по почте, даже как тайный друг. Каждый раз радуюсь, когда растёт счётчик отправленных. Какую бы вы отправили первой?`] },
];

// ——— 1691–1700: тулы для художников ———
const tools = [
  { type: 'tiles', th: 'paper', kick: 'free · for artists', h: 'A website full of <em>tools for artists</em>', cols: 2, link: '/', top: 290, tileH: 250,
    items: [{ src: 's5/mixing.png', crop: [60, 300, 1550, 1180], label: 'Colour mixing', sub: 'which real paints to mix' }, { art: '2025-pigeon-polly-romantizing-coffee-and-trains-in-autumn-vibes', label: 'Palettes', sub: 'six colours with HEX from every painting' }, { src: 's5/prompts.png', crop: [380, 110, 1300, 900], label: 'Monthly prompts', sub: '30 small themes to print' }, { src: 's5/challenge.png', crop: [60, 220, 1500, 1180], label: 'Daily challenge', sub: 'one subject, a few minutes' }, { src: 's5/freebies.png', crop: [190, 180, 1760, 1320], label: 'Free calendars', sub: 'and phone wallpapers' }, { src: 's5/learn.png', crop: [190, 180, 1770, 1320], label: 'Lessons', sub: 'watercolour and ink videos' }],
    cta: 'Explore the lab', tpl: 'Серия',
    title: 'A Free Website Full of Tools for Artists: Colour Mixing, Palettes, Prompts, Lessons',
    desc: 'Pigeon Polly Art Lab is my little website for people who draw: a colour mixing guide for watercolour, gouache and acrylic, palettes from my paintings with HEX codes, monthly drawing prompts, a daily sketch challenge, free calendars and video lessons.',
    alt: 'Six tiles of free art tools on pigeonpolly.com: colour mixing, palettes, monthly prompts, daily challenge, free calendars and lessons.',
    fb: ['A lab for people who draw', 'Про сайт', `My site started as a portfolio. Now it is more like a small art lab.\n\nThere is a colour mixing guide that tells you which real paints to mix. Palettes from my paintings with HEX codes. Thirty small drawing prompts every month. A daily sketch challenge where people share their drawings. Free calendars, wallpapers and video lessons. All of it free. What do you reach for most when you sit down to draw?`,
      `Мой сайт начинался как портфолио. Сейчас он больше похож на маленькую арт-лабораторию.\n\nЕсть подсказка по смешиванию, которая говорит, какие настоящие краски смешать. Палитры из моих картин с HEX-кодами. Тридцать небольших тем для рисования каждый месяц. Ежедневный челлендж, где люди делятся рисунками. Бесплатные календари, заставки и видеоуроки. Всё бесплатно. За чем вы тянетесь первым, когда садитесь рисовать?`] },
  { type: 'shot', th: 'paper', kick: 'colour mixing · free tool', h: 'Pick any colour. See <em>which paints</em> to mix.', src: 's5/mixing.png', crop: [60, 300, 1550, 1180], browser: 1, url: '/color-mixing/', link: '/color-mixing/',
    cap: 'watercolour · gouache · acrylic', chips: ['🎨 real paints', '📸 pick from your photo', '🧪 16 pigments'], cta: 'Mix a colour', tpl: 'Процесс',
    title: 'Free Colour Mixing Tool: Pick Any Colour and See Which Real Paints to Mix',
    desc: 'Choose watercolour, gouache or acrylic, pick a colour — or tap one on your own photo — and the colour mixing page on pigeonpolly.com shows which real paints to mix and how much of each, with colour theory tips and stories of 16 pigments.',
    alt: 'Screenshot of the colour mixing tool on pigeonpolly.com: choose your paint type, choose a colour, and get a mixing recipe from real pigments.',
    fb: ['How to mix any colour', 'Процесс', `“How do I mix this colour?” is the question I hear most from people who paint.\n\nSo my site now has a page for it. You choose watercolour, gouache or acrylic, pick the colour you want — or tap it on your own photo — and it tells you which real paints to mix and how much of each: peas of paint for gouache, brushfuls for watercolour. You can even choose your brand of paints. Which colour do you always struggle to mix?`,
      `«Как смешать этот цвет?» — вопрос, который я слышу чаще всего.\n\nТеперь на сайте есть для него страница. Выбираешь акварель, гуашь или акрил, нужный цвет — или нажимаешь на него на своём фото — и она подсказывает, какие настоящие краски смешать и сколько каждой: горошины для гуаши, кисти для акварели. Можно даже выбрать бренд своих красок. Какой цвет у вас никак не получается?`] },
  { type: 'palette', th: 'kraft', art: '2025-pigeon-polly-romantizing-coffee-and-trains-in-autumn-vibes', pos: '50% 45%', kick: '172 palettes · hex included', h: 'Palettes from <em>real paintings</em>', link: '/palettes/#2025-pigeon-polly-romantizing-coffee-and-trains-in-autumn-vibes', cta: 'Copy the colours', tpl: 'Палитра',
    title: 'Colour Palettes From Real Paintings With HEX Codes — 172 Free Palettes for Artists',
    desc: 'Every painting on pigeonpolly.com has its own palette: six colours with names and HEX codes, taken from the artwork itself. Copy a colour, pick a palette and draw. This one is “Night train in October”.',
    alt: 'Painting by Pigeon Polly of a pigeon on a night train with coffee, with a palette of six colours and HEX codes below.',
    fb: ['Palettes with HEX', 'Палитра', `Each of my paintings now has a palette next to it: six colours with names and HEX codes, taken from the painting itself.\n\nThere are 172 of them on my site. You can copy a colour with one tap and use it in a digital drawing, or just look at them when you don’t know where to start. This one is from “Night train in October”, coffee and a puffer jacket included. Do you choose colours first, or draw first?`,
      `У каждой моей картины теперь есть палитра: шесть цветов с названиями и HEX-кодами, взятых из самой картины.\n\nНа сайте их 172. Цвет можно скопировать одним нажатием и взять в цифровой рисунок, а можно просто смотреть, когда не знаешь, с чего начать. Эта — из «Ночного поезда в октябре», с кофе и пуховиком. Вы сначала выбираете цвета или сначала рисуете?`] },
  { type: 'shot', th: 'cream', kick: 'monthly prompts · free printable', h: '30 small drawing prompts <em>every month</em>', src: 's5/prompts.png', crop: [380, 110, 1300, 900], browser: 1, url: '/prompts/', link: '/prompts/',
    cap: 'save it, print it, tick it off', chips: ['🎨 three colours a day', '⏱ 5 to 15 minutes', '🖨 printable list'], cta: 'Get this month', tpl: 'Темы',
    title: 'Free Monthly Drawing Prompts to Save or Print — 30 Small Ideas, a Timer and 3 Colours',
    desc: 'Every month pigeonpolly.com has thirty small drawing prompts: one a day, three colours, a timer of five to fifteen minutes and a free printable list. Save it to your phone or print it for your desk.',
    alt: 'Screenshot of the monthly drawing prompts page on pigeonpolly.com with a month selector and buttons to save or print the list.',
    fb: ['Thirty small prompts', 'Бесплатное', `“I want to draw but I don’t know what” — the most common reason a sketchbook stays closed.\n\nSo every month my site has thirty small drawing prompts. One a day, three colours, a timer of five to fifteen minutes. You can save the list as an image or print it and stick it next to your desk. Small on purpose: a cup, a window, a sleepy cat. Do you prefer daily prompts or drawing whatever you like?`,
      `«Хочу рисовать, но не знаю что» — самая частая причина, по которой скетчбук остаётся закрытым.\n\nПоэтому каждый месяц на сайте тридцать маленьких тем. Одна в день, три цвета, таймер от пяти до пятнадцати минут. Список можно сохранить картинкой или распечатать и повесить у стола. Маленькие нарочно: чашка, окно, сонный кот. Вам больше нравятся темы на каждый день или рисовать что хочется?`] },
  { type: 'shot', th: 'night', kick: 'daily challenge · with the flock', h: 'One subject. A few colours. <em>A few minutes.</em>', src: 's5/challenge.png', crop: [60, 220, 1500, 1180], browser: 1, url: '/challenge/', link: '/challenge/',
    cap: 'and everyone shares what they drew', chips: ['📅 a new theme every day', '🖼 a wall of drawings'], cta: 'Draw today’s theme', tpl: 'Процесс',
    title: 'Daily Sketch Challenge: One Subject, a Few Colours, a Few Minutes — Free',
    desc: 'A daily sketch challenge with Pigeon Polly: every day one subject, a limited palette and a few minutes. Draw it, upload it, and see what everyone else drew on the community wall. Free on pigeonpolly.com.',
    alt: 'Screenshot of the Daily Challenge page on pigeonpolly.com with today’s drawing theme, a timer and a calendar of themes.',
    fb: ['A few minutes a day', 'Бесплатное', `The hardest part of drawing every day is not drawing. It is deciding what to draw.\n\nSo on my site there is a daily challenge: one subject, a few colours and a few minutes. You draw it in your sketchbook, take a photo, upload it — and it appears on the wall next to everyone else’s drawings of the same thing. It is lovely to see one cactus drawn fifty different ways. Would you join for a week?`,
      `Самое сложное в ежедневном рисовании — не рисовать, а решить, что рисовать.\n\nПоэтому на сайте есть ежедневный челлендж: одна тема, несколько цветов и несколько минут. Рисуешь в скетчбуке, фотографируешь, загружаешь — и рисунок появляется на стене рядом с рисунками всех остальных на ту же тему. Очень приятно видеть один кактус, нарисованный пятьюдесятью способами. Присоединились бы на неделю?`] },
  { type: 'shot', th: 'sky', kick: 'free course · 12 short lessons', h: 'Learn to see the world <em>like an artist</em>', src: 's5/helps.png', crop: [60, 180, 1870, 1320], browser: 1, url: '/polly-helps/', link: '/polly-helps/',
    cap: 'from simple shapes to a pixel diploma', chips: ['✏ paper and a pen', '🎓 12 lessons', '🌍 EN · RU · LV'], cta: 'Start lesson 1', tpl: 'Курс',
    title: 'Free Drawing Course for Beginners: See the World Like an Artist in 12 Short Lessons',
    desc: 'A free course of 12 short lessons on pigeonpolly.com: Polly the pigeon teaches you to see everything as simple shapes, then lines, shadows and composition — every lesson ends with a small task from a client from Wobbleland and a pixel diploma at the end.',
    alt: 'Screenshot of the free course “See the World Like an Artist” on pigeonpolly.com: a lesson about simple shapes with Polly as the teacher.',
    fb: ['Everything is a few shapes', 'Курс', `“I can’t even draw a straight line” — I hear this often, and it is never the real problem.\n\nThe real trick is to see a teapot as a circle and a triangle, a cat as two ovals. That is what the free course on my site teaches, in 12 short lessons. All you need is paper and a pen, Polly is your teacher, and at the end there is a pixel diploma. What would you like to be able to draw?`,
      `«Я даже прямую линию нарисовать не могу» — слышу это часто, и проблема никогда не в этом.\n\nНастоящий секрет — увидеть чайник как круг и треугольник, кошку как два овала. Этому учит бесплатный курс на сайте из 12 коротких уроков. Нужны только бумага и ручка, учитель — Полли, а в конце пиксельный диплом. Что бы вам хотелось уметь рисовать?`] },
  { type: 'shot', th: 'sage', kick: 'freebies · printable', h: 'Free <em>2027 calendars</em> with my art', src: 's5/freebies.png', crop: [190, 180, 1760, 1320], browser: 1, url: '/freebies/', link: '/freebies/', season: W,
    cap: 'monthly, yearly and for your phone', chips: ['📅 week from Monday or Sunday', '📱 phone wallpapers'], cta: 'Download free', tpl: 'Календарь',
    title: 'Free Printable 2027 Calendars With Watercolor Art — Monthly, Yearly and Phone Wallpapers',
    desc: 'Free printable 2027 calendars with paintings of Pigeon Polly: monthly and yearly, with weeks starting on Monday or Sunday, plus phone wallpapers. Download them on pigeonpolly.com.',
    alt: 'Screenshot of the Freebies page on pigeonpolly.com with printable 2027 calendars and phone wallpapers featuring watercolor paintings.',
    fb: ['Calendars for 2027', 'Бесплатное', `It is that time of the year when I start looking for a new calendar. So I made my own, and you can have it too.\n\nOn my site there are free 2027 calendars with my paintings: one for every month, one for the whole year, weeks starting on Monday or on Sunday, and wallpapers for your phone. Print them, put them on the fridge, change them every month. Paper calendar or phone calendar — which are you?`,
      `Самое время искать новый календарь. Поэтому я сделала свой, и он может быть и у вас.\n\nНа сайте бесплатные календари на 2027 год с моими картинами: на каждый месяц, на весь год, с неделей с понедельника или с воскресенья, и заставки на телефон. Распечатайте, повесьте на холодильник, меняйте каждый месяц. Вы за бумажный календарь или за календарь в телефоне?`, '2027'] },
  { type: 'shot', th: 'cream', kick: 'lessons · watercolour and ink', h: 'Paint small, <em>joyful things</em>', src: 's5/learn.png', crop: [190, 180, 1770, 1320], browser: 1, url: '/learn/', link: '/learn/',
    cap: 'free videos, open to everyone', chips: ['🎥 video lessons', '🖌 watercolour', '✒ ink'], cta: 'Watch a lesson', tpl: 'Курс',
    title: 'Free Watercolor and Ink Video Lessons — Paint Small, Joyful Things',
    desc: 'Watercolour and ink lessons by Alina Otkinska on pigeonpolly.com: free videos open to everyone and extra video lessons for signed-in visitors. Small, joyful subjects you can finish in one evening.',
    alt: 'Screenshot of the lessons page on pigeonpolly.com with watercolour and ink video lessons and course cards.',
    fb: ['Small, joyful things', 'Курс', `I don’t believe in talent. I believe in small paintings finished in one evening.\n\nThat is the idea behind the lessons on my site: watercolour and ink, short videos, simple subjects like a cup, a jar, a little house. Some videos are open to everyone, more are there for those who sign in. You paint along, pause when you need, and at the end there is something finished on your table. What would you paint first?`,
      `Я не верю в талант. Я верю в маленькие картинки, законченные за один вечер.\n\nНа этом построены уроки на сайте: акварель и тушь, короткие видео, простые сюжеты — чашка, банка, маленький дом. Часть видео открыта всем, ещё больше — для тех, кто вошёл. Рисуешь вместе, ставишь на паузу, когда нужно, и в конце на столе что-то законченное. Что бы вы нарисовали первым?`] },
  { type: 'shot', th: 'sun', kick: 'focus timer · for long drawing sessions', h: 'Draw for an hour while <em>Polly works next to you</em>', src: 'shots/shift.png', crop: [100, 0, 1500, 1106], link: '/shift/',
    cap: 'a pixel office and a retro tune', chips: ['⏱ 20 min to 3 hours', '🎵 retro music', '🏅 a promotion every hour'], cta: 'Start a shift', tpl: 'Процесс',
    title: 'A Cozy Pixel Focus Timer for Drawing Sessions — Work Next to a Pigeon',
    desc: 'Shift with Polly is a focus timer on pigeonpolly.com: pick 20 minutes to 3 hours and a retro tune, and Polly works at her pixel desk next to you. Every full hour brings a promotion and buttons. I use it for long painting sessions.',
    alt: 'Pixel art office with Polly the pigeon working at a desk, from the focus timer Shift with Polly on pigeonpolly.com.',
    fb: ['Body doubling with a pigeon', 'Про сайт', `Some days I can only work if someone else is working next to me. So I made Polly do it.\n\nShift with Polly is a focus timer on my site. You pick from 20 minutes to 3 hours and a retro tune, and pixel Polly sits at her desk in the office and works while you draw, write or study. Every full hour she gets a promotion. Do you focus better alone or with someone nearby?`,
      `Бывают дни, когда я могу работать, только если кто-то рядом тоже работает. Поэтому это делает Полли.\n\n«Смена с Полли» — таймер концентрации на сайте. Выбираешь от 20 минут до 3 часов и ретро-мелодию, и пиксельная Полли сидит за столом в офисе и работает, пока ты рисуешь, пишешь или учишься. За каждый полный час — повышение. Вам легче сосредоточиться одному или когда кто-то рядом?`] },
  { type: 'phone', th: 'paper', kick: 'colour mixing · from your photo', h: 'Found a colour you love? <em>Mix it.</em>', src: 's5/mixing-m.png', crop: [0, 600, 1170, 2400], link: '/color-mixing/?tab=find', top: 320,
    items: ['Upload a photo — the sea from your holiday, a café wall, your cat', 'Tap any spot with the pipette', 'See which real paints to mix and how much of each', 'Choose your own paints and brand', 'Save colours to your palette'],
    cta: 'Try with your photo', tpl: 'Процесс',
    title: 'How to Mix a Colour From Your Photo: Free Paint Mixing Tool for Watercolor and Gouache',
    desc: 'Upload your own photo to the colour mixing page on pigeonpolly.com, tap any spot with the pipette and see which real paints to mix and how much of each — for watercolour, gouache or acrylic, even with your own brand of paints.',
    alt: 'Phone screenshot of the colour mixing tool on pigeonpolly.com next to a list of steps for mixing a colour from your own photo.',
    fb: ['The colour of your holiday', 'Процесс', `There is a colour from my last summer that I keep trying to paint: the sea at about seven in the evening.\n\nOn my site you can upload a photo like that, tap the spot with a pipette, and it shows which real paints to mix to get close to it. You can tell it which paints you actually have, even the brand, and save your favourite colours. Which colour from a photo would you try first?`,
      `Есть цвет из прошлого лета, который я всё пытаюсь нарисовать: море примерно в семь вечера.\n\nНа сайте можно загрузить такое фото, нажать пипеткой на нужное место — и он покажет, какие настоящие краски смешать, чтобы подойти близко. Можно указать, какие краски у вас правда есть, даже бренд, и сохранить любимые цвета. Какой цвет с фото вы бы попробовали первым?`] },
];

// ——— 1701–1710: игры и вселенная ———
const games = [
  { type: 'tiles', th: 'night', kick: 'cozy games · a little universe', h: 'A cozy website with <em>games</em>', cols: 2, top: 290, tileH: 250,
    items: [{ src: 'shots/office.png', label: 'Polly’s Office', sub: 'sort Polly’s mail' }, { src: 'shots/titos.png', label: 'Detective Titos', sub: '100 cases' }, { src: 'shots/pancakes.png', crop: [0, 0, 880, 900], label: 'Polly’s Pancakes', sub: 'bake for Wobbleland' }, { src: 'shots/potions-winter.png', crop: [0, 0, 920, 900], label: 'Potion Lab', sub: 'mazes and recipes' }, { src: 'shots/rain.png', crop: [0, 0, 880, 900], label: 'Button Rain', sub: 'catch the buttons' }, { src: 'shots/wobble.png', label: 'Wobbleland', sub: 'a map of eleven towns' }],
    cta: 'Play for free', tpl: 'Серия',
    title: 'A Cozy Website With Free Pixel Games and Its Own Little Universe',
    desc: 'Pigeon Polly Art Lab has its own little universe: an island of eleven towns, a pigeon called Polly, a snail called Mr. Chew, a detective. And games — sort Polly’s mail, solve 100 detective cases, bake pancakes, brew potions in mazes, catch falling buttons. Free in the browser.',
    alt: 'Six pixel art game screenshots from pigeonpolly.com: Polly’s Office, Detective Titos, Polly’s Pancakes, Potion Lab, Button Rain and the Wobbleland map.',
    fb: ['A website with games', 'Про сайт', `Every artist’s website has a gallery. Mine also has a detective agency and a pancake shop.\n\nOver time my site grew its own little universe: an island of eleven towns, Polly the pigeon, Mr. Chew the snail, Detective Titos. And games: sort Polly’s mail in her office, solve a hundred cases, bake pancakes for the island, walk mazes for potion ingredients, catch falling buttons. Which one would you open first?`,
      `На сайте у художника обычно есть галерея. У меня ещё есть детективное агентство и блинная.\n\nСо временем у сайта появилась своя маленькая вселенная: остров из одиннадцати городов, голубь Полли, улитка Мистер Чу, детектив Титос. И игры: разобрать почту в офисе Полли, раскрыть сто дел, печь блины для острова, ходить по лабиринтам за ингредиентами зелий, ловить падающие пуговицы. Что бы вы открыли первым?`] },
  { type: 'shot', th: 'studio', kick: 'detective titos · 100 cases', h: 'Help a detective solve <em>100 cases</em>', src: 'shots/titos.png', crop: [200, 0, 1580, 1116], link: '/titos/',
    cap: 'and don’t let the coffee pot run dry', chips: ['🔎 find clues', '🗣 question suspects', '☕ coffee matters'], cta: 'Take a case', tpl: 'Арт',
    title: 'Cozy Detective Game in the Browser: Help Detective Titos Solve 100 Cases',
    desc: 'Detective Titos works late in his Snailhollow office. Help him solve a hundred cases in Wobbleland: find clues, pin the important ones, question suspects and keep the coffee pot from running dry. Free on pigeonpolly.com.',
    alt: 'Pixel art detective office at night with Detective Titos, a board with pinned clues, filing cabinets and a desk lamp.',
    fb: ['A hundred cases', 'Про сайт', `Detective Titos has a hundred cases on his desk and only one coffee pot.\n\nIt is a little detective game on my site. In every case you look at the scene, pin the important clues, check the small ones, question suspects — and keep an eye on the coffee, because without it Titos stops thinking. Each solved case brings a small thing for your pixel bird. Are you good at guessing who did it?`,
      `У детектива Титоса на столе сто дел и всего один кофейник.\n\nЭто маленькая детективная игра на сайте. В каждом деле осматриваешь место, прикалываешь важные улики, проверяешь мелочи, допрашиваешь подозреваемых — и следишь за кофе, потому что без него Титос перестаёт думать. За каждое раскрытое дело — маленькая вещь для пиксельной птички. Вы хорошо угадываете, кто виноват?`] },
  { type: 'shot', th: 'cream', kick: 'polly’s pancakes · a little game', h: 'Bake pancakes for <em>a whole island</em>', src: 'shots/pancakes.png', crop: [0, 0, 880, 760], link: '/pancakes/',
    cap: 'pick the pan, flip at the right moment', chips: ['🥞 endless levels', '🔘 earn buttons'], cta: 'Open the pancake shop', tpl: 'Арт',
    title: 'Cute Pixel Cooking Game: Bake Pancakes for the Residents of a Fairy-Tale Island',
    desc: 'Polly’s Pancakes is a little game on pigeonpolly.com: the residents of Wobbleland come to the window with orders. Pick the pan, flip at the right moment, add the toppings and earn buttons for the shop. Endless levels, free.',
    alt: 'Pixel art cooking game: an order from Miss Peony on a note, a big frying pan and Polly the pigeon in a chef hat.',
    fb: ['The pancake window', 'Про сайт', `“Polly, dear! Something sweet for my bakery break, please.” That is Miss Peony, and she is a regular.\n\nIn Polly’s Pancakes the residents of Wobbleland come to the window one by one. You choose the pan, flip at the right moment, add exactly the toppings they asked for — and get buttons to spend in the shop. It is my favourite game to play with tea. How do you like your pancakes?`,
      `«Полли, дорогая! Что-нибудь сладкое к перерыву, пожалуйста». Это мисс Пиони, она постоянная клиентка.\n\nВ «Блинной Полли» жители Воббленда по одному подходят к окошку. Выбираешь сковородку, переворачиваешь в нужный момент, кладёшь ровно ту начинку, которую просили, — и получаешь пуговки для магазина. Моя любимая игра под чай. А вы какие блины любите?`] },
  { type: 'shot', th: 'night', kick: 'potion lab · mazes and recipes', h: 'Find potion recipes <em>by trial and error</em>', src: 'shots/potions-winter.png', crop: [0, 0, 920, 800], link: '/potions/',
    cap: 'nobody knows the recipes. not even polly.', chips: ['🧪 collect ingredients', '🌀 endless mazes'], cta: 'Enter the lab', tpl: 'Арт',
    title: 'Cozy Pixel Maze Game: Collect Ingredients and Discover Potion Recipes',
    desc: 'In Polly’s Potion Lab you walk endless mazes with your pixel bird, collect ingredients and discover potion recipes by trial and error — nobody tells you the recipes. Earn buttons for the shop. Free on pigeonpolly.com.',
    alt: 'Pixel art maze game in winter colours with a small pigeon, ghosts and ingredients to collect, from Polly’s Potion Lab.',
    fb: ['Nobody knows the recipes', 'Про сайт', `The best thing about Polly’s Potion Lab is that nobody tells you the recipes.\n\nYou walk through mazes with your pixel bird, avoid the ghosts, collect ingredients, and then try combinations in the cauldron. Some become potions, some become nonsense. Every discovered recipe goes into your book. It started as a Halloween game, and now it has a winter version too. Do you read instructions, or just try things?`,
      `Лучшее в Зельеварне Полли — что рецепты никто не рассказывает.\n\nХодишь по лабиринтам с пиксельной птичкой, обходишь привидений, собираешь ингредиенты, а потом пробуешь сочетания в котле. Что-то становится зельем, что-то — ерундой. Каждый открытый рецепт попадает в книгу. Начиналось как игра к Хэллоуину, а теперь есть и зимняя версия. Вы читаете инструкции или сразу пробуете?`] },
  { type: 'shot', th: 'sun', kick: 'polly’s train · a word game', h: 'Go by train and <em>learn words</em>', src: 's5/train.png', crop: [60, 180, 1560, 1320], browser: 1, url: '/train/', link: '/train/',
    cap: 'Spain, Norway, Great Britain or Latvia', chips: ['🚆 endless stations', '🔤 make words from letters', '🔘 earn buttons'], cta: 'Board the train', tpl: 'Арт',
    title: 'Cozy Word Game: Travel by Train to Spain, Norway, Britain or Latvia and Learn Words',
    desc: 'Polly’s Train is a word game on pigeonpolly.com with Empanadillo from Libertas.study: go by train to Spain, Norway, Great Britain or Latvia, make words out of letters in the language of that country, learn what they mean and earn buttons. Endless stations.',
    alt: 'Screenshot of Polly’s Train, a pixel word game on pigeonpolly.com with a train to Spain and a choice of countries.',
    fb: ['A train for words', 'Про сайт', `I am learning Norwegian, and I needed a game where words come to you on a train.\n\nIn Polly’s Train you choose a country — Spain, Norway, Great Britain or Latvia — and at every station you make words out of letters in that language, then see what they mean. Polly travels with Empanadillo from Libertas.study. The stations never end. Which language would you take the train to?`,
      `Я учу норвежский, и мне нужна была игра, где слова приезжают на поезде.\n\nВ «Поезде Полли» выбираешь страну — Испанию, Норвегию, Великобританию или Латвию — и на каждой станции собираешь слова из букв на этом языке, а потом узнаёшь, что они значат. Полли едет вместе с Эмпанадильо из Libertas.study. Станции не кончаются. В какой язык вы бы поехали?`] },
  { type: 'shot', th: 'sky', kick: 'button rain · a tiny game', h: 'Catch the buttons, <em>dodge the ink</em>', src: 'shots/rain.png', crop: [0, 0, 880, 760], link: '/rain/',
    cap: 'every level a little faster', chips: ['🔘 buttons for the shop', '♾ endless levels'], cta: 'Play Button Rain', tpl: 'Арт',
    title: 'Tiny Cozy Browser Game: Catch Falling Buttons With a Pixel Pigeon, Dodge Ink Blots',
    desc: 'Button Rain is a little Pigeon Polly game: catch falling buttons with your pixel bird, dodge the ink blots and earn buttons for the shop. Endless levels, every one a little faster. Free on pigeonpolly.com.',
    alt: 'Pixel art game Button Rain: a small purple pigeon on green grass catching colourful buttons falling from a blue sky, with an ink blot.',
    fb: ['Five minutes of buttons', 'Про сайт', `My smallest game, and the one I play when I have exactly five minutes.\n\nButton Rain: buttons fall from the sky, your pixel bird runs left and right to catch them, and ink blots fall too, so you have to dodge. Every level is a bit faster. The buttons you catch are real currency on my site: you can spend them on hats, scarves and things for your bird’s room. What is your five-minute game?`,
      `Моя самая маленькая игра, в которую я играю, когда есть ровно пять минут.\n\n«Пуговичный дождь»: с неба падают пуговицы, пиксельная птичка бегает влево-вправо и ловит их, а ещё падают кляксы — от них надо уворачиваться. Каждый уровень чуть быстрее. Пойманные пуговки на сайте — настоящая валюта: на них покупают шапки, шарфы и вещи для комнаты птички. А какая у вас игра на пять минут?`] },
  { type: 'shot', th: 'cream', kick: 'polly’s office · click everything', h: 'Polly got an <em>office job</em>', src: 'shots/office.png', crop: [0, 0, 1500, 1116], link: '/polly-office/',
    cap: '“an urgent email from the Council… help me?”', capfs: 46, chips: ['📮 sort the mail', '🌇 switch to evening'], cta: 'Visit the office', tpl: 'Мем',
    title: 'Cozy Pixel Office Game: Help a Pigeon Clerk Sort Her Mail',
    desc: 'Polly went back to the office: old blinds, a water cooler and a desk you can click. An urgent email from the Council has scattered her report all over the room — help her sort the mail. Switch to evening and watch the light change. Free on pigeonpolly.com.',
    alt: 'Pixel art office with Polly the pigeon in a scarf, a desk with a computer, bookshelves and a speech bubble about an urgent email.',
    fb: ['Back to the office', 'Полли', `After six years of working from home, Polly got an office job. She is not thrilled.\n\nOn my site you can visit her pixel office: old blinds, a water cooler, a desk where everything can be clicked. Today an urgent email from the Council has scattered her report all over the room, and she needs help sorting the mail. You can also switch to evening and watch the light change. Office or home — where do you work better?`,
      `После шести лет удалёнки Полли устроилась в офис. Она не в восторге.\n\nНа сайте можно заглянуть в её пиксельный офис: старые жалюзи, кулер, стол, где можно нажать на всё. Сегодня срочное письмо от Совета разбросало её отчёт по всей комнате, и ей нужна помощь с почтой. Ещё можно переключить на вечер и смотреть, как меняется свет. Офис или дом — где вам лучше работается?`] },
  { type: 'shot', th: 'paper', kick: 'new here?', h: 'Everyone who signs in gets <em>a pixel bird</em>', src: 's5/how.png', crop: [180, 150, 1780, 1350], browser: 1, url: '/how/', link: '/how/', top: 340,
    cap: 'with a room, a garden and a bag of gifts', chips: ['🐦 your own bird', '🔘 buttons from games', '🛍 a bird market'], cta: 'Hatch my bird', tpl: 'Арт',
    title: 'A Cozy Art Website Where You Get Your Own Pixel Bird, Room and Garden',
    desc: 'On pigeonpolly.com everyone who signs in gets a pixel bird. Earn buttons in games, spend them at the bird market on hats, scarves and room things, plant a garden that follows the real season, and join the flock.',
    alt: 'Screenshot of the “What is this place?” guide on pigeonpolly.com with a drawing of the flock of pixel birds and buttons to hatch your bird.',
    fb: ['Your own pixel bird', 'Про сайт', `When you sign in on my site, you hatch a little pixel bird. It is yours.\n\nIt has a room you can furnish, a garden behind the house where you plant seeds and water them every day, and a bag of gifts. You earn buttons in the games and spend them at the bird market on hats, scarves and furniture. And all the birds together live in a flock. What would you name yours?`,
      `Когда входишь на сайт, у тебя вылупляется маленькая пиксельная птичка. Она твоя.\n\nУ неё есть комната, которую можно обставить, сад за домом, где сажаешь семена и поливаешь каждый день, и мешочек с подарками. Пуговки зарабатываешь в играх и тратишь на птичьем рынке на шапки, шарфы и мебель. А все птички вместе живут стаей. Как бы вы назвали свою?`] },
  { type: 'shot', th: 'night', kick: 'advent calendar', h: 'A street of <em>31 windows</em>', src: 's5/advent.png', crop: [200, 1000, 1760, 500], ih: 780, link: '/advent/', season: W,
    cap: 'one window lights up every day', chips: ['🎄 1 Dec to 31 Dec', '🎁 a gift in every window'], cta: 'Open today’s window', tpl: 'Адвент',
    title: 'A Cozy Pixel Advent Calendar: a Street of 31 Windows, One Lights Up Every Day',
    desc: 'A street of 31 little houses on pigeonpolly.com: every day from December 1 one more window lights up, and there is a gift inside. Come back every day, or catch up later.',
    alt: 'Pixel art night street of colourful little houses with dark windows under a moon, the advent calendar “A street of 31 windows” on pigeonpolly.com.',
    fb: ['A street of 31 windows', 'Про сайт', `Every December I want an advent calendar, and every December I eat it in three days. So I made one you can’t eat.\n\nOn my site there is a little pixel street of 31 houses. From December 1, one window lights up every day, and there is a gift inside. I won’t tell you what — that is the whole point. Do you open advent windows one by one, or all at once?`,
      `Каждый декабрь хочу адвент-календарь и каждый декабрь съедаю его за три дня. Поэтому сделала такой, который не съесть.\n\nНа сайте маленькая пиксельная улица из 31 домика. С 1 декабря каждый день загорается одно окошко, а внутри подарок. Какой — не скажу, в этом весь смысл. Вы открываете окошки по одному или все сразу?`, 'Рождество'] },
  { type: 'tiles', th: 'rose', kick: 'the cast', h: 'Meet the <em>Pigeon Polly universe</em>', cols: 2, top: 320, tileH: 370,
    items: [{ art: '2026-pigeon-polly-keeps-busy-living', label: 'Polly', sub: 'a pigeon, not quite ordinary' }, { art: '2023-mr-chew-coffee-passion', label: 'Mr. Chew', sub: 'a snail who loves coffee' }, { art: '2024-detective-mr-titos-in-the-office-late-night', label: 'Detective Titos', sub: 'works late in Snailhollow' }, { art: 'halloween-in-blue', label: 'The Pumpkins', sub: 'Kettleford’s finest' }],
    cta: 'Meet them all', tpl: 'Серия', link: '/wobbleland/',
    title: 'Meet the Characters: a Pigeon, a Coffee-Loving Snail, a Detective and a Pumpkin Family',
    desc: 'The little universe of pigeonpolly.com: Polly, a pigeon who is not quite ordinary; Mr. Chew, a snail who loves coffee; Detective Titos, who works late in Snailhollow; and the Pumpkin Family of Kettleford. They all live on the island of Wobbleland.',
    alt: 'Four watercolor paintings by Pigeon Polly of her characters: Polly the pigeon, Mr. Chew the snail, Detective Titos and a pumpkin butler.',
    fb: ['The cast', 'Искусство', `People who follow me for a while start asking: wait, who is who? So here is the cast.\n\nPolly, a pigeon who insists she is not quite an ordinary representative of her species. Mr. Chew, a snail with a serious coffee habit. Detective Titos, who works late in his office in Snailhollow. And the Pumpkin Family of Kettleford, who are very polite. They all live on the same island, Wobbleland. Who is your favourite?`,
      `Те, кто давно за мной следит, начинают спрашивать: подождите, кто есть кто? Вот вся компания.\n\nПолли — голубь, которая настаивает, что она не совсем обычный представитель своего вида. Мистер Чу — улитка с серьёзной кофейной привычкой. Детектив Титос, который засиживается в офисе в Snailhollow. И очень вежливое семейство Тыкв из Kettleford. Все они живут на одном острове, в Воббленде. Кто ваш любимый?`] },
];

// ——— 1711–1720: темы для рисования (открытые списки → /prompts/) ———
const themes = [
  { art: 'sketchbook-13', pos: '50% 50%', th: 'cream', kick: 'drawing prompts', h: '20 things to draw at a <em>bakery window</em>', items: ['a cinnamon roll from above', 'a croissant, one continuous line', 'a tray of tiny tarts', 'the baker’s hands in flour', 'a paper bag with a stain', 'a price tag in chalk', 'a cake under a glass dome', 'a loaf with a cut on top', 'a crumb trail', 'steam on the glass', 'a cupcake with one cherry', 'a row of baguettes', 'the queue outside', 'a cookie with a bite', 'a jam jar on the counter', 'a bun shaped like an animal', 'the shop sign', 'a cup of coffee to go', 'a doughnut, three colours', 'the last éclair'],
    title: '20 Things to Draw at a Bakery Window — Cozy Food Sketchbook Prompts',
    desc: 'A cinnamon roll from above, a croissant in one line, steam on the glass, the last éclair. Twenty cozy bakery drawing prompts for your sketchbook. More small prompts every month on pigeonpolly.com.',
    alt: 'List of 20 bakery drawing prompts next to an ink and watercolour sketch of a pastry counter by Pigeon Polly.',
    fb: ['Drawing at the bakery', 'Скетчбук', `If you don’t know what to draw this week, go stand by a bakery window.\n\nA cinnamon roll from above. A croissant in one continuous line. Steam on the glass. A tray of tiny tarts. A loaf with a cut on top. The last éclair that somebody is about to take. The pastry counter in this sketch is from one of those mornings when I came for bread and stayed for an hour with my sketchbook. What would you draw first?`,
      `Если не знаете, что рисовать на этой неделе, встаньте у витрины пекарни.\n\nБулочка с корицей сверху. Круассан одной линией. Пар на стекле. Поднос с крошечными тартами. Буханка с надрезом. Последний эклер, который вот-вот кто-то заберёт. Эта витрина — из утра, когда я пришла за хлебом и осталась на час со скетчбуком. Что бы вы нарисовали первым?`] },
  { art: '2025-mr-chew-travel-edition-can-you-find-polly', pos: '50% 40%', th: 'kraft', kick: 'drawing prompts', h: '20 <em>lost-and-found</em> things to draw', items: ['one glove', 'an umbrella with a broken spoke', 'a key with a funny keychain', 'a library book, 3 years late', 'a single earring', 'a teddy bear on a bench', 'a scarf on a fence', 'reading glasses', 'a ticket from 1999', 'a sock behind the radiator', 'a lost cat poster', 'a lunchbox with a name', 'a phone charger', 'a postcard never sent', 'a toy car in the sand', 'a hat on a lamp post', 'a suitcase with stickers', 'a ring in a coat pocket', 'a shoe on the beach', 'a note: “if found, call…”'],
    title: '20 Lost-and-Found Things to Draw — Storytelling Sketchbook Prompts',
    desc: 'One glove, a library book three years late, a teddy bear on a bench, a postcard never sent. Twenty lost-and-found drawing prompts — every object is a little story. More prompts every month on pigeonpolly.com.',
    alt: 'List of 20 lost-and-found drawing prompts next to a painting by Pigeon Polly of a snail with a suitcase shell covered in travel stickers.',
    fb: ['Lost and found', 'Скетчбук', `In Wobbleland there is a man called Mr. Crisper who keeps the lost-and-found boxes at the train station. I often think about what is in them.\n\nOne glove. An umbrella with a broken spoke. A library book three years late. A teddy bear someone left on a bench. A postcard that was never sent. Every lost thing is a tiny story, and a perfect drawing prompt. What is the strangest thing you have ever lost?`,
      `В Воббленде есть мистер Криспер, который хранит коробки потерянных вещей на вокзале. Я часто думаю, что в них лежит.\n\nОдна перчатка. Зонт со сломанной спицей. Библиотечная книга, просроченная на три года. Мишка, забытый на скамейке. Открытка, которую так и не отправили. Каждая потерянная вещь — маленькая история и отличная тема для рисунка. Что самое странное вы теряли?`] },
  { art: '2024-mr-chew-gardening-edition', pos: '50% 45%', th: 'sage', kick: 'drawing prompts', h: '20 drawing prompts: <em>a snail who…</em>', items: ['…runs a tiny café', '…is late for a train', '…carries a house that’s too small', '…delivers the mail', '…grows tomatoes on its shell', '…goes on a first date', '…is afraid of salt', '…wins a slow race', '…reads under a mushroom', '…knits a shell cosy', '…works in an office', '…goes to the seaside', '…has a very long to-do list', '…opens a shop on a leaf', '…is a detective', '…wears rain boots', '…celebrates a birthday', '…moves to a new shell', '…drinks too much coffee', '…waits for spring'],
    title: '20 Cute Snail Drawing Ideas — “A Snail Who…” Character Prompts',
    desc: 'A snail who runs a tiny café, is late for a train, grows tomatoes on its shell or drinks too much coffee. Twenty cute snail character prompts for your sketchbook, from the artist behind Mr. Chew. More prompts on pigeonpolly.com.',
    alt: 'List of 20 “a snail who…” drawing prompts next to a watercolour of Mr. Chew the snail gardening, by Pigeon Polly.',
    fb: ['A snail who…', 'Мистер Чу', `Mr. Chew has been a postman, a Santa, a detective, a gardener and a coffee addict. Snails make wonderful characters.\n\nSo here is a game for your sketchbook: finish the sentence “a snail who…”. Runs a tiny café. Is late for a train. Carries a house that is too small. Goes on a first date. Is afraid of salt. Wins a slow race. Draw one a day and you have a whole snail town by the end of the month. Which one would you draw?`,
      `Мистер Чу был почтальоном, Сантой, детективом, садовником и кофеманом. Улитки — прекрасные персонажи.\n\nВот игра для скетчбука: закончите фразу «улитка, которая…». Держит крошечное кафе. Опаздывает на поезд. Носит слишком маленький дом. Идёт на первое свидание. Боится соли. Выигрывает медленную гонку. Одна в день — и к концу месяца у вас целый улиточный город. Какую бы вы нарисовали?`] },
  { art: 'studio-yoga', pos: '50% 50%', th: 'pink', kick: 'drawing prompts', h: '20 prompts: a <em>pigeon doing human things</em>', items: ['doing yoga', 'stuck in a video call', 'waiting for a bus', 'reading the news, worried', 'in a bubble bath', 'at a job interview', 'carrying too many shopping bags', 'on a night train with coffee', 'assembling furniture', 'writing a thesis', 'at the dentist', 'learning to skate', 'hiding something behind its back', 'on a beach lounger', 'drinking from the brush water', 'making the logo bigger', 'in a queue at the post office', 'asleep on the sofa', 'opening a small business', 'celebrating New Year in bed'],
    title: '20 Funny Drawing Prompts: a Pigeon Doing Human Things',
    desc: 'A pigeon doing yoga, stuck in a video call, assembling furniture, drinking the brush water by accident. Twenty funny character prompts — many of them have already happened to Polly in my paintings. More prompts on pigeonpolly.com.',
    alt: 'List of 20 funny drawing prompts about a pigeon doing human things next to a painting of a pigeon doing yoga by Pigeon Polly.',
    fb: ['A pigeon doing human things', 'Полли', `Half of my paintings are just a pigeon doing very human things.\n\nPolly has done yoga, written a thesis, gone back to an office job, drunk the brush water by accident, opened an ice cream van and celebrated New Year in bed. So here is a prompt list for your sketchbook: draw a pigeon waiting for a bus, assembling furniture, stuck in a video call, at the dentist. Which one sounds most like your week?`,
      `Половина моих картин — это просто голубь, который делает очень человеческие вещи.\n\nПолли занималась йогой, писала диплом, вернулась в офис, случайно выпила воду для кисточек, открыла фургон с мороженым и встретила Новый год в кровати. Вот список тем: нарисуйте голубя на остановке, собирающим мебель, на видеозвонке, у стоматолога. Какая тема больше всего похожа на вашу неделю?`] },
  { art: '2025-pigeon-polly-romantizing-coffee-and-trains-in-autumn-vibes', pos: '50% 50%', th: 'night', kick: 'drawing prompts', h: '20 things to draw from a <em>train window</em>', items: ['a field with one tree', 'a station at night', 'your reflection on the glass', 'rain drops racing', 'a cup on the little table', 'power lines like music staves', 'a small town’s rooftops', 'a level crossing', 'cows that don’t look up', 'a river under a bridge', 'the conductor’s hat', 'a sleeping passenger', 'a forest in one colour', 'the sunset in 3 strokes', 'your ticket', 'a lit window of a house', 'snow on the platform', 'the luggage rack', 'a tunnel, almost black', 'the moment you arrive'],
    title: '20 Things to Draw From a Train Window — Travel Sketchbook Prompts',
    desc: 'A field with one tree, power lines like music staves, rain drops racing on the glass, a lit window of a house far away. Twenty train-window drawing prompts for your travel sketchbook. More prompts every month on pigeonpolly.com.',
    alt: 'List of 20 train window drawing prompts next to a painting by Pigeon Polly of a pigeon with coffee on a night train in October.',
    fb: ['From a train window', 'Скетчбук', `I love drawing on trains, even though the train never waits for me to finish.\n\nThat is the fun of it: a field with one tree is gone in three seconds, so you draw fast. Power lines like music staves. Rain drops racing on the glass. Your own reflection. A lit window of a house far away. The painting here is Polly on a night train in October, with coffee and a donut. Do you draw while travelling, or just look?`,
      `Я люблю рисовать в поезде, хотя поезд никогда не ждёт, пока я закончу.\n\nВ этом и прелесть: поле с одним деревом исчезает за три секунды, поэтому рисуешь быстро. Провода как нотный стан. Капли, которые наперегонки бегут по стеклу. Своё отражение. Горящее окно далёкого дома. На картине — Полли в ночном поезде в октябре, с кофе и пончиком. Вы рисуете в дороге или просто смотрите?`] },
  { art: '2024-detective-mr-titos-in-the-office-late-night', pos: '50% 45%', th: 'studio', kick: 'drawing prompts', h: '20 <em>cozy mystery</em> things to draw', items: ['a magnifying glass', 'footprints in snow', 'a desk lamp at 2 am', 'a cork board with red string', 'a coffee pot, almost empty', 'a torn train ticket', 'a fingerprint', 'a locked drawer', 'a suspect’s hat', 'a cup with lipstick', 'a mysterious letter', 'rain on the office window', 'a filing cabinet', 'a cat who saw everything', 'a dropped glove', 'a candle burnt to the end', 'a door left half open', 'a clock stopped at 9:15', 'a notebook of clues', 'the detective, finally sleeping'],
    title: '20 Cozy Mystery Things to Draw — Detective Sketchbook Prompts',
    desc: 'A magnifying glass, footprints in snow, a cork board with red string, a coffee pot almost empty, a clock stopped at 9:15. Twenty cozy mystery drawing prompts for your sketchbook. More prompts every month on pigeonpolly.com.',
    alt: 'List of 20 cozy mystery drawing prompts next to a painting by Pigeon Polly of a detective working late at night in his office.',
    fb: ['Cozy mystery prompts', 'Скетчбук', `Some evenings ask for a cozy mystery: rain outside, a lamp, a cup of something hot.\n\nSo here is a list for those evenings. A magnifying glass. Footprints in the snow. A cork board with red string. A coffee pot that is almost empty. A clock stopped at 9:15. A cat who saw everything and says nothing. The painting is Detective Titos, working late in his office. Do you like mystery books, films or games most?`,
      `Некоторые вечера просят уютного детектива: дождь за окном, лампа, чашка чего-то горячего.\n\nВот список для таких вечеров. Лупа. Следы на снегу. Пробковая доска с красной нитью. Почти пустой кофейник. Часы, остановившиеся на 9:15. Кот, который всё видел и молчит. На картине — детектив Титос, засидевшийся в офисе. Что вы любите больше — детективные книги, фильмы или игры?`] },
  { art: 'studio-desk_night', pos: '50% 50%', th: 'paper', kick: 'drawing prompts', h: '20 things <em>in your bag</em> to draw', items: ['your keys, all of them', 'a crumpled receipt', 'a lip balm', 'headphones in a knot', 'a pen that doesn’t work', 'a half-eaten snack', 'your wallet, open', 'a hair tie', 'a bus ticket', 'sunglasses', 'a tiny sketchbook', 'a water bottle', 'coins', 'a plaster', 'a shopping list', 'your phone, face down', 'a tote bag inside the bag', 'a cough drop', 'a spare sock (why?)', 'the bag itself, from above'],
    title: '20 Things in Your Bag to Draw — Easy Everyday Sketchbook Prompts',
    desc: 'Your keys, a crumpled receipt, headphones in a knot, a pen that doesn’t work, a spare sock (why?). Twenty everyday things to draw from your own bag — no reference photo needed. More prompts every month on pigeonpolly.com.',
    alt: 'List of 20 everyday drawing prompts about things in your bag next to a painting of an artist’s desk at night by Pigeon Polly.',
    fb: ['What is in your bag', 'Скетчбук', `The best drawing reference is already in your bag.\n\nEmpty it on the table and draw what falls out. Your keys, all of them. A crumpled receipt. Headphones in a hopeless knot. A pen that doesn’t work but you keep anyway. Half a snack. A spare sock that nobody can explain. It is one of my favourite exercises: no photos, no searching, just your own life. What is the strangest thing in your bag right now?`,
      `Лучшая натура для рисунка уже лежит в вашей сумке.\n\nВысыпьте её на стол и рисуйте, что выпало. Ключи, все. Мятый чек. Наушники в безнадёжном узле. Ручку, которая не пишет, но вы её храните. Половину перекуса. Запасной носок, который никто не может объяснить. Одно из моих любимых упражнений: без фото, без поисков, просто своя жизнь. Что самое странное в вашей сумке прямо сейчас?`] },
  { art: 'studio-bookshop', pos: '50% 50%', th: 'night', kick: 'drawing prompts', h: '20 <em>tiny shop fronts</em> to draw', items: ['a bookshop at night', 'a flower stall', 'a bakery with a striped awning', 'a tiny post office', 'a shoe repair', 'a tea shop with jars', 'a record store', 'a toy shop window', 'a corner café', 'a hat shop', 'a fish market stall', 'a pharmacy with an old sign', 'a key-cutting kiosk', 'a candle shop', 'a vintage clothes shop', 'a cheese shop', 'a noodle bar', 'a button and thread shop', 'a lemonade stand', 'a shop for one thing only'],
    title: '20 Tiny Shop Fronts to Draw — Cozy Urban Sketching Prompts',
    desc: 'A bookshop at night, a tea shop with jars, a button and thread shop, a noodle bar, a shop that sells only one thing. Twenty cozy shop fronts to draw — real or invented. More prompts every month on pigeonpolly.com.',
    alt: 'List of 20 tiny shop front drawing prompts next to a painting of a glowing bookshop window at night by Pigeon Polly.',
    fb: ['Tiny shop fronts', 'Скетчбук', `I could draw shop windows forever. A lit bookshop at night is my weakness.\n\nHere are twenty shop fronts to try, real or invented: a flower stall, a tea shop with jars, a record store, a key-cutting kiosk, a button and thread shop, a noodle bar, and my favourite — a shop that sells only one thing. Invent what it sells. What would your tiny shop sell?`,
      `Я могла бы рисовать витрины бесконечно. Освещённый книжный ночью — моя слабость.\n\nВот двадцать витрин, настоящих или придуманных: цветочный ларёк, чайная лавка с банками, магазин пластинок, будка, где делают ключи, лавка пуговиц и ниток, лапшичная — и моя любимая: магазин, где продают только одну вещь. Придумайте какую. Что продавал бы ваш маленький магазин?`] },
  { art: 'sketchbook-5', pos: '50% 50%', th: 'sun', kick: 'drawing prompts', h: '20 <em>comfort food</em> things to draw', items: ['a bowl of noodles from above', 'soup with steam', 'a grilled cheese, pulled apart', 'porridge with jam', 'dumplings in a basket', 'a pie, one slice missing', 'pancakes with syrup dripping', 'a mug of cocoa with marshmallows', 'toast with butter melting', 'a pot on the stove', 'mashed potatoes, a lake of butter', 'a ramen egg, cut in half', 'cookies on a tray', 'a bread bowl of soup', 'rice with a fried egg', 'a stew in a small pot', 'a cheese board', 'fries in a paper cone', 'a fortune cookie', 'leftovers at midnight'],
    title: '20 Comfort Food Things to Draw — Cozy Food Sketchbook Prompts',
    desc: 'A bowl of noodles from above, soup with steam, a grilled cheese pulled apart, pancakes with syrup dripping, leftovers at midnight. Twenty cozy comfort food drawing prompts. More prompts every month on pigeonpolly.com.',
    alt: 'List of 20 comfort food drawing prompts next to a watercolour sketch of a cozy breakfast by Pigeon Polly.',
    fb: ['Comfort food', 'Скетчбук', `Food is the friendliest thing to draw: it doesn’t move, and afterwards you can eat the model.\n\nTwenty cozy ideas for cold evenings: noodles from above, soup with steam, a grilled cheese pulled apart, dumplings in a basket, pancakes with syrup dripping, a mug of cocoa, and leftovers at midnight. The sketch here is a breakfast I painted before eating it. What is your comfort food?`,
      `Еда — самое дружелюбное, что можно рисовать: она не двигается, а потом модель можно съесть.\n\nДвадцать уютных идей для холодных вечеров: лапша сверху, суп с паром, растянутый горячий бутерброд с сыром, пельмени в корзинке, блины, с которых стекает сироп, кружка какао и остатки ужина в полночь. Здесь — завтрак, который я нарисовала, прежде чем съесть. Какая у вас любимая утешительная еда?`] },
  { art: 'studio-moka_rust', pos: '50% 50%', th: 'kraft', kick: 'drawing prompts', h: '20 things from a <em>tea & coffee corner</em>', items: ['a moka pot', 'a teapot with a chipped lid', 'a kettle whistling', 'coffee beans, 5 of them', 'a tea bag hanging over a cup', 'a French press', 'sugar cubes', 'a cup from above, with foam', 'a cezve on the stove', 'a jar of loose tea', 'a spoon in honey', 'a stack of saucers', 'a coffee stain ring', 'a milk jug', 'cinnamon sticks', 'a thermos', 'a cup with a funny face', 'a coffee grinder', 'steam in three lines', 'the last biscuit'],
    title: '20 Things to Draw From a Tea and Coffee Corner — Cozy Kitchen Sketch Ideas',
    desc: 'A moka pot, a teapot with a chipped lid, a tea bag hanging over a cup, a coffee stain ring, steam in three lines, the last biscuit. Twenty cozy tea and coffee drawing prompts. More prompts every month on pigeonpolly.com.',
    alt: 'List of 20 tea and coffee drawing prompts next to a painting of a rusty moka pot by Pigeon Polly.',
    fb: ['The tea and coffee corner', 'Скетчбук', `If I had to draw only one corner of my home for a year, it would be the one with the kettle.\n\nA moka pot. A teapot with a chipped lid. A tea bag hanging over the edge of a cup. A ring of coffee on the table. Steam in three lines. The last biscuit that nobody dares to take. In Wobbleland there is even a whole town for this, Kettleford, where every house has at least three kettles. Tea or coffee?`,
      `Если бы год можно было рисовать только один уголок дома, я выбрала бы тот, где чайник.\n\nКофеварка-мока. Заварочный чайник со сколом на крышке. Чайный пакетик, свисающий с края чашки. Кофейное кольцо на столе. Пар тремя линиями. Последнее печенье, которое никто не решается взять. В Воббленде для этого есть целый город, Kettleford, где в каждом доме минимум три чайника. Чай или кофе?`] },
].map(p => ({ type: 'list', cta: 'More prompts', tpl: 'Темы', season: Y, ...p }));

module.exports = { TOP, wl, pc, tools, games, themes };
